    { id: 'C-001', name: 'Northwind Studio', email: 'info@northwind.example', tier: 'gold' },
    { id: 'C-002', name: 'Acme Corp', email: 'contact@acme.example', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2024-0001', status: 'issued' },
    { customerId: 'C-002', number: 'INV-2024-0002', status: 'issued' },
    { customerId: 'C-001', number: 'INV-2024-0003', status: 'draft' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-002');
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers normalizes customer ids', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'info@northwind.example', tier: 'gold' },
    { id: 'C-002', name: 'Acme Corp', email: 'contact@acme.example', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2024-0001', status: 'issued' },
